style.css:
@-moz-document domain("chat.openai.com") {
body {
    background: linear-gradient(to bottom, #f9d7dc 0%, #fff7e0 50%, #d6c3af 100%) !important;
    color: #5a3e36 !important;
  }

  .text-base, .prose, .markdown {
    color: #5a3e36 !important;
  }

  .bg-token-main-surface, .bg-token-surface-primary, .bg-token-surface-secondary {
    background-color: transparent !important;
  }

  .rounded-md, .rounded-xl, .px-4, .py-2, .mb-4 {
    background-color: rgba(255, 255, 255, 0.7) !important;
    border: 1px solid #d6c3af !important;
    border-radius: 16px !important;
  }

  .text-token-text-primary {
    color: #5a3e36 !important;
  }

  ::selection {
    background: #fbc4c4 !important;
    color: #5a3e36 !important;
  }

  a {
    color: #c97a6d !important;
  }

  .btn, button, .text-token-text-secondary {
    background-color: #f2e4dc !important;
    color: #5a3e36 !important;
    border-radius: 12px !important;
  }

  input, textarea {
    background-color: #fffaf2 !important;
    color: #5a3e36 !important;
    border: 1px solid #d6c3af !important;
  }
}
